  minf = excluded.minf, maxf = excluded.maxf, st = excluded.st, weight = excluded.weight, price = excluded.price;

on conflict (id) do update set name = excluded.name, phase = excluded.phase, rarity = excluded.rarity, image = excluded.image,
  minf = excluded.minf, maxf = excluded.maxf, st = excluded.st, weight = excluded.weight, price = excluded.price;

on conflict (id) do update set name = excluded.name, image = excluded.image, price = excluded.price, ev = excluded.ev,
  sort = excluded.sort, released = excluded.released, active = true, cat = excluded.cat;

